import type { CSSProperties } from 'react'

import { cx } from '~/lib/cx'
import styles from './skeleton.module.scss'

export type SkeletonVariant = 'block' | 'text' | 'rect' | 'circle'

const VARIANT: Record<SkeletonVariant, string> = {
  block: styles.block,
  text: styles.text,
  rect: styles.rect,
  circle: styles.circle,
}

export interface SkeletonProps {
  variant?: SkeletonVariant
  width?: CSSProperties['width']
  height?: CSSProperties['height']
  className?: string
}

/** A layout-stable placeholder. Marked `aria-hidden`; pair with live status copy. */
export function Skeleton({
  variant = 'block',
  width,
  height,
  className,
}: SkeletonProps) {
  return (
    <div
      aria-hidden
      className={cx(styles.root, VARIANT[variant], className)}
      style={{ width, height }}
    />
  )
}

@use 'styles' as vz;

.root {
  --skeleton-radius: #{vz.radius('md')};

  position: relative;
  overflow: hidden;
  border-radius: var(--skeleton-radius);
  background: vz.color('muted');
  animation: vz-skeleton-pulse 1.8s vz.ease('in-out') infinite;

  @include vz.motion-reduce {
    animation: none;
  }
}

.root::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent,
    hsl(var(--foreground) / 6%),
    transparent
  );
  transform: translateX(-100%);
  animation: vz-skeleton-sweep 1.8s vz.ease('in-out') infinite;

  @include vz.motion-reduce {
    animation: none;
    display: none;
  }
}

.text {
  width: 100%;
  height: 0.8em;

  --skeleton-radius: #{vz.radius('xs')};
}

.circle {
  border-radius: vz.radius('full');
}

.rect {
  --skeleton-radius: #{vz.radius('lg')};
}

.block {
  width: 100%;
  height: 6rem;

  --skeleton-radius: #{vz.radius('xl')};
}

@keyframes vz-skeleton-pulse {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.72;
  }
}

@keyframes vz-skeleton-sweep {
  to {
    transform: translateX(100%);
  }
}
